function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var SS={days:['Before','Day 1','Day 2','Day 3','Day 4','Day 5','After'],current:2,hours_done:6,hours_total:16,next:'Interview two front-line staff',review:['Current-state map (since Nov 10)'],comments:3,details:[{key:'Working on now:',text:'Tool inventory'},{key:'Waiting on:',text:'Access to the shared drive (asked Nov 9)'}]};
function kitStatusStrip(host,d,uid){var s=document.createElement('section');s.className='sstrip';s.setAttribute('aria-labelledby',uid);var it=function(k,v){return v?'<span><b>'+kEsc(k)+'</b> '+kEsc(v)+'</span>':'';};var started=d.current!==undefined&&d.current!==null;var h='<h2 class="sstrip-h" id="'+uid+'">Where things stand</h2><div class="sstrip-line">';
if(started){var done=d.hours_done+' of '+d.hours_total+' hours done';h+='<span class="sstrip-segs" role="progressbar" aria-label="Progress by day" aria-valuemin="0" aria-valuemax="'+Math.max(d.days.length-1,1)+'" aria-valuenow="'+d.current+'" aria-valuetext="'+kEsc(d.days[d.current]+', '+done)+'">'+d.days.map(function(x,i){return '<span class="sstrip-seg'+(i<d.current?' is-done':i===d.current?' is-now':'')+'"></span>';}).join('')+'</span><span class="sstrip-done">'+kEsc(d.days[d.current])+' · '+kEsc(done)+'</span>';}else h+='<span class="sstrip-done"><b>Not started.</b></span>';
h+=it('Up next:',d.next)+it('Ready for your review:',(d.review||[]).join('; '))+(d.comments?it('Comments so far:',d.comments+' batched for the review call'):'');
var more=(d.details||[]).map(function(x){return '<p><b>'+kEsc(x.key)+'</b> '+kEsc(x.text)+'</p>';}).join('');if(more)h+='<details class="sstrip-det"><summary>Details</summary><div class="sstrip-more">'+more+'</div></details>';s.innerHTML=h+'</div>';host.appendChild(s);return s;}
kitStatusStrip(kSlot(),SS,'ss-stage').classList.add('is-top');
STATES.forEach(function(s,i){var d=s[0].started?SS:{days:SS.days,next:'Kickoff call'};kitStatusStrip(kSlot(i),d,'ss-s'+i);});
